require_relative "notification_time"

# An invitation number is generated by its sender, not allocated globally.
# Scope it with the room and both authenticated users already present in the
# native invitation / notification. Old ID-only entry points may choose only
# an unambiguous scope; they must never pick the first colliding invitation.
module GameRoomInvitationIdentity
  FIELDS = %w[table_id live_session_id sender recipient].freeze
  module_function

  def row(reference)
    reference = reference.invitation if reference.respond_to?(:invitation)
    return reference if reference.is_a?(Hash)

    { "__id" => reference.respond_to?(:id) ? reference.id : reference }
  end

  def id(reference)
    value = row(reference)
    (value["__id"] || value["id"] || value["invitation_id"]).to_i
  end

  def key(reference)
    value = row(reference)
    [id(value), value["table_id"].to_i, value["live_session_id"].to_s.dup.freeze,
      value["sender"].to_s.downcase.freeze, value["recipient"].to_s.downcase.freeze].freeze
  end

  def matches?(candidate, reference)
    expected, actual = row(reference), row(candidate)
    return false unless id(expected).positive? && id(actual) == id(expected)

    FIELDS.all? do |field|
      wanted = expected[field]
      next true if wanted.nil? || wanted.to_s.empty?

      if field == "table_id"
        actual[field].to_i == wanted.to_i
      elsif %w[sender recipient].include?(field)
        actual[field].to_s.casecmp?(wanted.to_s)
      else
        actual[field].to_s == wanted.to_s
      end
    end
  end

  def unique(items, reference)
    matches = items.select { |item| matches?(block_given? ? yield(item) : item, reference) }
    scopes = matches.group_by { |item| key(block_given? ? yield(item) : item) }
    scopes.size == 1 ? matches.first : nil
  end

  # A completed request still belongs to the account and authenticated endpoint
  # which issued it. Never continue its remaining steps on a replacement runtime.
  def account_guard(transport:, user:, recipient: nil)
    account = user.call.to_s.dup.freeze
    endpoint, authenticated_user = transport.invitation_account_identity
    lambda do
      current_endpoint, current_user = transport.invitation_account_identity
      !account.empty? && account.casecmp?(user.call.to_s) &&
        account.casecmp?(authenticated_user) && account.casecmp?(current_user) &&
        endpoint.equal?(current_endpoint) && (recipient.nil? || account.casecmp?(recipient.to_s))
    end
  end

  def notification_reference(notification, recipient:)
    metadata = notification.metadata.to_h.transform_keys(&:to_s)
    return nil unless valid_notification_metadata?(metadata)
    sender = notification_sender(notification, metadata)
    return nil if sender.nil?

    { "__id" => metadata["invitation_id"], "table_id" => metadata["table_id"],
      "live_session_id" => metadata["live_session_id"], "sender" => sender,
      "recipient" => recipient.to_s }
  end

  # Presentation, filtering and lookup must agree on the native envelope.
  # Older adapters have no sender accessor; only those retain the metadata
  # fallback. A missing metadata name must not hide the authenticated name.
  def notification_sender(notification, metadata)
    claimed = (metadata["sender"] || metadata[:sender]).to_s
    return claimed unless notification.respond_to?(:sender)

    sender = notification.sender.to_s
    return nil if sender.empty? || (!claimed.empty? && !sender.casecmp?(claimed))

    sender
  end

  def valid_notification_metadata?(metadata)
    GameRoomNotificationTime.valid_metadata?(metadata) && %w[invitation_id table_id].all? do |key|
      GameRoomNotificationTime.integer_value?(metadata.key?(key) ? metadata[key] : metadata[key.to_sym])
    end
  end
end
